// sparktree: sparktree reads slash-separated hierarchy paths with numeric series and prints a tree with a sparkline per node.
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"math"
	"os"
	"runtime/debug"
	"strconv"
	"strings"
)

// version is set at release time with -ldflags "-X main.version=v1.2.3".
var version = ""

const usage = `sparktree reads slash-separated hierarchy paths with numeric series and prints a tree with a sparkline per node.

Usage:
  sparktree [file ...]

Examples:
  printf 'api/users 1 3 2\napi/orders 2 2 5\n' | sparktree
  sparktree metrics.txt
  sparktree a.txt b.txt

Flags:
`

type node struct {
	name     string
	children []*node
	series   []float64
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// run is the whole program. It returns the exit code:
// 0 success, 1 failure, 2 usage error.
func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("sparktree", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {}
	showVersion := fs.Bool("version", false, "print version and exit")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(stdout, usage)
			fs.SetOutput(stdout)
			fs.PrintDefaults()
			return 0
		}
		fmt.Fprintln(stderr, "Run 'sparktree -h' for usage.")
		return 2
	}
	if *showVersion {
		fmt.Fprintln(stdout, buildVersion())
		return 0
	}

	files := fs.Args()
	root := &node{}
	code := 0
	if len(files) == 0 {
		if f, ok := stdin.(*os.File); ok {
			if st, err := f.Stat(); err == nil && st.Mode()&os.ModeCharDevice != 0 {
				fmt.Fprintln(stderr, "Run 'sparktree -h' for usage.")
				return 2
			}
		}
		code = parse(stdin, root, stderr)
	}
	for _, name := range files {
		f, err := os.Open(name)
		if err != nil {
			fmt.Fprintf(stderr, "sparktree: cannot read %s: %v\n", name, err)
			code = 1
			continue
		}
		code = max(code, parse(f, root, stderr))
		f.Close()
	}
	render(stdout, root.children, "", true)
	return code
}

// parse adds the lines of r to root and returns 1 if any line was malformed.
func parse(r io.Reader, root *node, stderr io.Writer) int {
	data, err := io.ReadAll(r)
	code := 0
	if err != nil {
		fmt.Fprintf(stderr, "sparktree: %v\n", err)
		code = 1
	}
	for i, line := range strings.Split(string(data), "\n") {
		if reason := addLine(line, root); reason != "" {
			fmt.Fprintf(stderr, "sparktree: line %d: %s\n", i+1, reason)
			code = 1
		}
	}
	return code
}

func addLine(line string, root *node) string {
	f := strings.Fields(line)
	if len(f) == 0 {
		return ""
	} else if len(f) < 2 {
		return "no numbers"
	}
	series := make([]float64, len(f)-1)
	for i, s := range f[1:] {
		v, err := strconv.ParseFloat(s, 64)
		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) || v < 0 {
			return fmt.Sprintf("invalid or negative number %q", s)
		}
		series[i] = v
	}
	segs := strings.Split(f[0], "/")
	for _, s := range segs {
		if s == "" {
			return "empty path segment"
		}
	}
	n := root
	for _, s := range segs {
		var c *node
		for _, x := range n.children {
			if x.name == s {
				c = x
			}
		}
		if c == nil {
			c = &node{name: s}
			n.children = append(n.children, c)
		}
		n = c
		n.series = append(n.series, make([]float64, max(0, len(series)-len(n.series)))...)
		for i, v := range series {
			n.series[i] += v
		}
	}
	return ""
}

func spark(s []float64) string {
	m := 0.0
	for _, v := range s {
		m = math.Max(m, v)
	}
	blocks, out := []rune("▁▂▃▄▅▆▇"), make([]rune, len(s))
	for i, v := range s {
		if m != 0 && v != 0 {
			out[i] = blocks[min(6, max(0, int(math.Ceil(v*7/m))-1))]
		} else {
			out[i] = blocks[0]
		}
	}
	return string(out)
}

func render(w io.Writer, nodes []*node, prefix string, top bool) {
	for i, n := range nodes {
		conn, ext := "", ""
		if !top && i < len(nodes)-1 {
			conn, ext = "├── ", "│   "
		} else if !top {
			conn, ext = "└── ", "    "
		}
		line := prefix + conn + n.name + " " + spark(n.series)
		if len(n.children) > 0 {
			t := 0.0
			for _, v := range n.series {
				t += v
			}
			line += " " + strconv.FormatFloat(t, 'f', -1, 64)
		}
		fmt.Fprintln(w, line)
		render(w, n.children, prefix+ext, false)
	}
}

func buildVersion() string {
	if version != "" {
		return version
	}
	if bi, ok := debug.ReadBuildInfo(); ok && bi.Main.Version != "" {
		return bi.Main.Version
	}
	return "dev"
}

