// uuidtime: uuidtime extracts the timestamp from UUIDv1/v7 values, or generates a UUIDv7 for a given time with -g.
package main

import (
	"bufio"
	"crypto/rand"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"regexp"
	"runtime/debug"
	"strconv"
	"strings"
	"time"
	_ "time/tzdata"
)

// version is set at release time with -ldflags "-X main.version=v1.2.3".
var version = ""

const usage = `uuidtime extracts the timestamp from UUIDv1/v7 values, or generates a UUIDv7 for a given time with -g.

Usage:
  uuidtime [-z zone] [-g time] [uuid...]

Examples:
  uuidtime 018f3b2e-7c00-7000-8000-000000000000
  uuidtime -z Asia/Tokyo 018f3b2e-7c00-7000-8000-000000000000
  uuidtime -g 2024-05-02T21:20:53Z

Flags:
`

var (
	uuidRe = regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
	intRe  = regexp.MustCompile(`^-?[0-9]+$`)
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

func parseGen(v string, loc *time.Location) (int64, bool) {
	var ms int64
	ok := false
	if intRe.MatchString(v) {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			return 0, false
		}
		ms, ok = n, true
		if n > -100000000000 && n < 100000000000 {
			ms = n * 1000
		}
	} else if t, err := time.Parse(time.RFC3339, v); err == nil {
		ms, ok = t.UnixMilli(), true
	} else {
		for _, l := range []string{"2006-01-02T15:04:05", "2006-01-02"} {
			if t, err := time.ParseInLocation(l, v, loc); err == nil {
				ms, ok = t.UnixMilli(), true
				break
			}
		}
	}
	if !ok || ms < 0 || ms >= 1<<48 {
		return 0, false
	}
	return ms, true
}

// extract returns unix ms or an error message.
func extract(in string) (int64, string) {
	if !uuidRe.MatchString(in) {
		return 0, "invalid UUID"
	}
	ver, _ := strconv.ParseUint(in[14:15], 16, 8)
	switch ver {
	case 7:
		n, _ := strconv.ParseUint(in[0:8]+in[9:13], 16, 64)
		return int64(n), ""
	case 1:
		lo, _ := strconv.ParseUint(in[0:8], 16, 64)
		mid, _ := strconv.ParseUint(in[9:13], 16, 64)
		hi, _ := strconv.ParseUint(in[14:18], 16, 64)
		ticks := (hi&0x0FFF)<<48 | mid<<32 | lo
		return (int64(ticks) - 122192928000000000) / 10000, ""
	}
	return 0, fmt.Sprintf("unsupported version %d", ver)
}

// run is the whole program. It returns the exit code:
// 0 success, 1 failure, 2 usage error.
func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("uuidtime", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {}
	showVersion := fs.Bool("version", false, "print version and exit")
	zone := fs.String("z", "UTC", "IANA time zone for displayed datetimes and for -g datetimes without an offset")
	gen := fs.String("g", "", "generate a UUIDv7 for this time (RFC 3339 datetime, YYYY-MM-DD, or Unix time)")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(stdout, usage)
			fs.SetOutput(stdout)
			fs.PrintDefaults()
			return 0
		}
		fmt.Fprintln(stderr, "Run 'uuidtime -h' for usage.")
		return 2
	}
	if *showVersion {
		fmt.Fprintln(stdout, buildVersion())
		return 0
	}

	loc, err := time.LoadLocation(*zone)
	if err != nil {
		fmt.Fprintln(stderr, "uuidtime: invalid time zone: "+*zone)
		return 2
	}

	if *gen != "" {
		if fs.NArg() > 0 {
			fmt.Fprintln(stderr, "uuidtime: unexpected arguments with -g")
			return 2
		}
		ms, ok := parseGen(*gen, loc)
		if !ok {
			fmt.Fprintln(stderr, "uuidtime: invalid -g value: "+*gen)
			return 2
		}
		var b [16]byte
		if _, err := rand.Read(b[:]); err != nil {
			fmt.Fprintln(stderr, "uuidtime: "+err.Error())
			return 1
		}
		for i := 0; i < 6; i++ {
			b[i] = byte(ms >> (8 * (5 - i)))
		}
		b[6] = 0x70 | b[6]&0x0f
		b[8] = 0x80 | b[8]&0x3f
		fmt.Fprintf(stdout, "%x-%x-%x-%x-%x\n", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
		return 0
	}

	var inputs []string
	if fs.NArg() > 0 {
		for _, a := range fs.Args() {
			inputs = append(inputs, strings.TrimSpace(a))
		}
	} else {
		if f, ok := stdin.(*os.File); ok {
			if st, err := f.Stat(); err == nil && st.Mode()&os.ModeCharDevice != 0 {
				fmt.Fprintln(stderr, "Run 'uuidtime -h' for usage.")
				return 2
			}
		}
		sc := bufio.NewScanner(stdin)
		sc.Buffer(make([]byte, 64*1024), 1<<20)
		for sc.Scan() {
			if l := strings.TrimSpace(sc.Text()); l != "" {
				inputs = append(inputs, l)
			}
		}
	}
	if len(inputs) == 0 {
		fmt.Fprintln(stderr, "uuidtime: no input")
		return 2
	}
	code := 0
	for _, in := range inputs {
		ms, msg := extract(in)
		if msg != "" {
			fmt.Fprintf(stderr, "uuidtime: %s: %s\n", in, msg)
			code = 1
			continue
		}
		t := time.UnixMilli(ms).In(loc)
		fmt.Fprintf(stdout, "%d %s\n", ms, t.Format("2006-01-02T15:04:05.000Z07:00"))
	}
	return code
}

func buildVersion() string {
	if version != "" {
		return version
	}
	if bi, ok := debug.ReadBuildInfo(); ok && bi.Main.Version != "" {
		return bi.Main.Version
	}
	return "dev"
}

