// uuidera: uuidera reads v1 or v7 UUIDs from arguments or stdin and prints their embedded time in JST with the Japanese era.
package main

import (
	"bufio"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"runtime/debug"
	"strconv"
	"strings"
	"time"
)

// version is set at release time with -ldflags "-X main.version=v1.2.3".
var version = ""

const usage = `uuidera reads v1 or v7 UUIDs from arguments or stdin and prints their embedded time in JST with the Japanese era.

Usage:
  uuidera [uuid ...]

Examples:
  uuidera 017F22E2-79B0-7CC3-98C4-DC0C0C07398F
  uuidera 13814000-1DD2-11B2-8000-000000000000
  echo 00000000-0000-7000-8000-000000000000 | uuidera

Flags:
`

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// run is the whole program. It returns the exit code:
// 0 success, 1 failure, 2 usage error.
func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("uuidera", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {}
	showVersion := fs.Bool("version", false, "print version and exit")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(stdout, usage)
			fs.SetOutput(stdout)
			fs.PrintDefaults()
			return 0
		}
		fmt.Fprintln(stderr, "Run 'uuidera -h' for usage.")
		return 2
	}
	if *showVersion {
		fmt.Fprintln(stdout, buildVersion())
		return 0
	}

	var inputs []string
	if fs.NArg() > 0 {
		inputs = fs.Args()
	} else {
		if f, ok := stdin.(*os.File); ok {
			if st, err := f.Stat(); err == nil && st.Mode()&os.ModeCharDevice != 0 {
				fmt.Fprintln(stderr, "Run 'uuidera -h' for usage.")
				return 2
			}
		}
		sc := bufio.NewScanner(stdin)
		sc.Buffer(make([]byte, 64*1024), 16*1024*1024)
		for sc.Scan() {
			inputs = append(inputs, sc.Text())
		}
		if err := sc.Err(); err != nil {
			fmt.Fprintln(stderr, "uuidera: "+err.Error())
			return 1
		}
	}

	code := 0
	for _, in := range inputs {
		in = strings.TrimSpace(in)
		if in == "" {
			continue
		}
		out, msg := convert(in)
		if msg != "" {
			fmt.Fprintf(stderr, "uuidera: %s: %s\n", in, msg)
			code = 1
			continue
		}
		fmt.Fprintln(stdout, out)
	}
	return code
}

func validUUID(s string) bool {
	if len(s) != 36 {
		return false
	}
	for i := 0; i < 36; i++ {
		c := s[i]
		if i == 8 || i == 13 || i == 18 || i == 23 {
			if c != '-' {
				return false
			}
			continue
		}
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

type era struct {
	name    string
	y, m, d int
}

var eras = []era{
	{"令和", 2019, 5, 1},
	{"平成", 1989, 1, 8},
	{"昭和", 1926, 12, 25},
	{"大正", 1912, 7, 30},
	{"明治", 1873, 1, 1},
}

func convert(in string) (string, string) {
	if !validUUID(in) {
		return "", "invalid UUID"
	}
	h := func(s string) uint64 {
		v, _ := strconv.ParseUint(s, 16, 64)
		return v
	}
	ver := h(in[14:15])
	var t time.Time
	switch ver {
	case 1:
		ticks := h(in[15:18])<<48 | h(in[9:13])<<32 | h(in[0:8])
		sec := int64(ticks/10000000) - 12219292800
		t = time.Unix(sec, 0)
	case 7:
		ms := h(in[0:8])<<16 | h(in[9:13])
		t = time.Unix(int64(ms/1000), 0)
	default:
		return "", fmt.Sprintf("unsupported version %d", ver)
	}
	t = t.In(time.FixedZone("JST", 9*3600))
	y, mo, d := t.Date()
	key := y*10000 + int(mo)*100 + d
	date := ""
	for _, e := range eras {
		if key >= e.y*10000+e.m*100+e.d {
			ey := strconv.Itoa(y - e.y + 1)
			if y-e.y+1 == 1 {
				ey = "元"
			}
			date = fmt.Sprintf("%s%s年%d月%d日", e.name, ey, int(mo), d)
			break
		}
	}
	if date == "" {
		date = fmt.Sprintf("%d年%d月%d日", y, int(mo), d)
	}
	return fmt.Sprintf("%s %s %02d:%02d:%02d JST", in, date, t.Hour(), t.Minute(), t.Second()), ""
}

func buildVersion() string {
	if version != "" {
		return version
	}
	if bi, ok := debug.ReadBuildInfo(); ok && bi.Main.Version != "" {
		return bi.Main.Version
	}
	return "dev"
}

