// tsbar: tsbar reads UNIX timestamps one per line and prints a horizontal bar chart of counts per minute, hour or day.
package main

import (
	"bufio"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"runtime/debug"
	"strconv"
	"strings"
	"time"
)

// version is set at release time with -ldflags "-X main.version=v1.2.3".
var version = ""

const usage = `tsbar reads UNIX timestamps one per line and prints a horizontal bar chart of counts per minute, hour or day.

Usage:
  tsbar [-u minute|hour|day] [-w width] [-z] [file ...]

Examples:
  tsbar -w 20 times.txt
  tsbar -u day -z times.txt more.txt
  cat times.txt | tsbar -u minute

Flags:
`

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// run is the whole program. It returns the exit code:
// 0 success, 1 failure, 2 usage error.
func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("tsbar", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.Usage = func() {}
	showVersion := fs.Bool("version", false, "print version and exit")
	unitName := fs.String("u", "hour", "bucket unit: minute, hour or day")
	width := fs.Int("w", 40, "maximum bar width in blocks (at least 1)")
	utc := fs.Bool("z", false, "use UTC instead of JST (UTC+9)")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			fmt.Fprint(stdout, usage)
			fs.SetOutput(stdout)
			fs.PrintDefaults()
			return 0
		}
		fmt.Fprintln(stderr, "Run 'tsbar -h' for usage.")
		return 2
	}
	if *showVersion {
		fmt.Fprintln(stdout, buildVersion())
		return 0
	}

	var unit int64
	switch *unitName {
	case "minute":
		unit = 60
	case "hour":
		unit = 3600
	case "day":
		unit = 86400
	default:
		fmt.Fprintf(stderr, "tsbar: invalid unit %q: must be minute, hour or day\n", *unitName)
		return 2
	}
	if *width < 1 {
		fmt.Fprintln(stderr, "tsbar: width must be at least 1")
		return 2
	}
	var offset int64 = 9 * 3600
	if *utc {
		offset = 0
	}

	files := fs.Args()
	if len(files) == 0 {
		if f, ok := stdin.(*os.File); ok {
			if st, err := f.Stat(); err == nil && st.Mode()&os.ModeCharDevice != 0 {
				fmt.Fprintln(stderr, "Run 'tsbar -h' for usage.")
				return 2
			}
		}
	}

	code := 0
	counts := map[int64]int64{}
	var minB, maxB int64
	have := false
	notDigit := func(r rune) bool { return r < '0' || r > '9' }

	process := func(name string, r io.Reader) {
		br := bufio.NewReader(r)
		ln := 0
		for {
			line, err := br.ReadString('\n')
			if line != "" {
				ln++
				t := strings.TrimSpace(line)
				if t == "" {
				} else if len(t) > 18 || strings.IndexFunc(t, notDigit) >= 0 {
					fmt.Fprintf(stderr, "tsbar: %s:%d: invalid timestamp %q\n", name, ln, t)
					code = 1
				} else {
					v, _ := strconv.ParseInt(t, 10, 64)
					if len(t) >= 13 {
						v /= 1000
					}
					v += offset
					b := v - v%unit
					counts[b]++
					if !have || b < minB {
						minB = b
					}
					if !have || b > maxB {
						maxB = b
					}
					have = true
				}
			}
			if err != nil {
				if err != io.EOF {
					fmt.Fprintf(stderr, "tsbar: %v\n", err)
					code = 1
				}
				return
			}
		}
	}

	if len(files) == 0 {
		process("stdin", stdin)
	}
	for _, name := range files {
		f, err := os.Open(name)
		if err != nil {
			fmt.Fprintf(stderr, "tsbar: %v\n", err)
			code = 1
			continue
		}
		process(name, f)
		f.Close()
	}

	if !have {
		return code
	}
	if (maxB-minB)/unit+1 > 100000 {
		fmt.Fprintln(stderr, "tsbar: range too large")
		return 1
	}
	var max int64
	for _, c := range counts {
		if c > max {
			max = c
		}
	}
	var sb strings.Builder
	for b := minB; b <= maxB; b += unit {
		c := counts[b]
		n := c * int64(*width) / max
		if c > 0 && n == 0 {
			n = 1
		}
		sb.WriteString(time.Unix(b, 0).UTC().Format("2006-01-02 15:04"))
		sb.WriteString(" " + strings.Repeat("█", int(n)) + " ")
		sb.WriteString(strconv.FormatInt(c, 10) + "\n")
	}
	io.WriteString(stdout, sb.String())
	return code
}

func buildVersion() string {
	if version != "" {
		return version
	}
	if bi, ok := debug.ReadBuildInfo(); ok && bi.Main.Version != "" {
		return bi.Main.Version
	}
	return "dev"
}
